//! Reader for `nm-settings-docs-dbus.xml`, the connection-profile property table.
//!
//! A connection profile travels as `a{sa{sv}}` — a map of setting name to a map of property
//! name to variant — which is the least typed thing in NetworkManager's whole D-Bus API. This
//! module reads what each of those properties actually is, so it can be given a real field.
//!
//! The file is generated by NetworkManager itself, merging its introspection data with the
//! `---dbus---` comment blocks in its sources. That merge is why the file is used rather than
//! the introspection data directly: about thirty properties travel as something other than
//! their GObject type, and NetworkManager has already reconciled the two.

use anyhow::{Context, Result, bail};

#[derive(Debug, Clone)]
pub struct Setting {
    /// The key under which the setting appears in a profile, e.g. `802-11-wireless`.
    pub name: String,
    /// The field it becomes on a profile, e.g. `wireless`.
    pub field_name: String,
    /// The struct generated for it, e.g. `WirelessSetting`.
    pub struct_name: String,
    pub doc: Option<String>,
    pub properties: Vec<Property>,
}

#[derive(Debug, Clone)]
pub struct Property {
    /// The key under which the property appears in the setting, e.g. `mac-address`.
    pub name: String,
    /// The field it becomes, e.g. `mac_address`.
    pub field_name: String,
    pub ty: PropertyType,
    /// The value NetworkManager uses when the property is absent, as it documents it.
    pub default: Option<String>,
    pub doc: Option<String>,
}

/// What a connection-profile property is, on the wire.
///
/// Deliberately a closed set: [`PropertyType::parse`] rejects anything it does not recognise,
/// so a type NetworkManager introduces later stops generation instead of being quietly dropped
/// or, worse, guessed at.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PropertyType {
    Bool,
    Byte,
    Int32,
    Uint32,
    Int64,
    Uint64,
    Str,
    StrArray,
    ByteArray,
    ByteArrayArray,
    Uint32Array,
    Uint32ArrayArray,
    /// `a{ss}`, e.g. `vpn.data`.
    StringMap,
    /// `aa{sv}`, e.g. `ipv4.address-data`. The keys vary by property and are not described
    /// here, so these stay maps.
    VardictArray,
    /// One of NetworkManager's enumerations or flag sets, named as it is in the headers.
    Named { c_name: String },
    /// `a(ayuay)` — `ipv6.addresses`, kept for compatibility by NetworkManager.
    LegacyIp6Addresses,
    /// `a(ayuayu)` — `ipv6.routes`, likewise.
    LegacyIp6Routes,
}

impl PropertyType {
    /// The D-Bus signature a value of this type travels as.
    pub fn signature(&self) -> &'static str {
        match self {
            Self::Bool => "b",
            Self::Byte => "y",
            Self::Int32 => "i",
            Self::Uint32 => "u",
            Self::Int64 => "x",
            Self::Uint64 => "t",
            Self::Str => "s",
            Self::StrArray => "as",
            Self::ByteArray => "ay",
            Self::ByteArrayArray => "aay",
            Self::Uint32Array => "au",
            Self::Uint32ArrayArray => "aau",
            Self::StringMap => "a{ss}",
            Self::VardictArray => "aa{sv}",
            Self::LegacyIp6Addresses => "a(ayuay)",
            Self::LegacyIp6Routes => "a(ayuayu)",
            // Filled in from the enumeration's own resolved width.
            Self::Named { .. } => "",
        }
    }

    /// Read one of the type strings the table uses.
    ///
    /// Named types are written with their width in brackets — `NMTernary (int32)` — which is
    /// dropped here: the width comes from the enumeration itself, and disagreeing with it would
    /// mean the two halves of the generated code did not match.
    pub fn parse(text: &str) -> Result<Self> {
        if let Some(name) = text.strip_prefix("NM") {
            let c_name = format!("NM{}", name.split_whitespace().next().unwrap_or_default());
            return Ok(Self::Named { c_name });
        }

        Ok(match text {
            "boolean" => Self::Bool,
            "byte" => Self::Byte,
            "int32" => Self::Int32,
            "uint32" => Self::Uint32,
            "int64" => Self::Int64,
            "uint64" => Self::Uint64,
            "string" => Self::Str,
            // NetworkManager writes this both ways.
            "array of string" | "array of strings" => Self::StrArray,
            "byte array" => Self::ByteArray,
            "array of byte array" => Self::ByteArrayArray,
            "array of uint32" => Self::Uint32Array,
            "array of array of uint32" => Self::Uint32ArrayArray,
            "dict of string to string" => Self::StringMap,
            "array of vardict" | "array of 'a{sv}'" => Self::VardictArray,
            "array of legacy IPv6 address struct (a(ayuay))" => Self::LegacyIp6Addresses,
            "array of legacy IPv6 route struct (a(ayuayu))" => Self::LegacyIp6Routes,
            other => bail!(
                "unrecognised property type `{other}` — it needs a mapping in \
                 codegen/src/settings.rs before it can be generated"
            ),
        })
    }
}

/// Read the settings table.
///
/// `field_name_overrides` supplies a name for the settings whose own name cannot open a Rust
/// identifier and whose upper-case form cannot either — `6lowpan`, `802-1x`. A setting that
/// needs one and does not have one is an error rather than a mangled guess.
pub fn parse(source: &str, field_name_overrides: &[(String, String)]) -> Result<Vec<Setting>> {
    let document = roxmltree::Document::parse(source).context("parsing the settings table")?;
    let root = document
        .descendants()
        .find(|node| node.has_tag_name("nm-setting-docs"))
        .context("no <nm-setting-docs> element")?;

    let mut settings = Vec::new();
    for node in root.children().filter(|n| n.has_tag_name("setting")) {
        let name = node.attribute("name").context("a <setting> without a name")?;

        let field_name = field_name(name, node.attribute("name_upper"), field_name_overrides)
            .with_context(|| {
                format!(
                    "`{name}` needs a `[[setting]]` entry in annotations.toml giving the name it \
                     should take, since neither its own name nor its upper-case form can open a \
                     Rust identifier"
                )
            })?;

        let mut properties = Vec::new();
        for property in node.children().filter(|n| n.has_tag_name("property")) {
            let property_name = property
                .attribute("name")
                .with_context(|| format!("a property of `{name}` without a name"))?;
            let Some(type_text) = property.attribute("type").filter(|t| !t.is_empty()) else {
                // `802-11-wireless.security` is documented as having no type: it is a
                // deprecated no-op that NetworkManager ignores.
                continue;
            };
            let ty = PropertyType::parse(type_text)
                .with_context(|| format!("the type of `{name}.{property_name}`"))?;

            properties.push(Property {
                field_name: field_ident(property_name),
                name: property_name.to_owned(),
                ty,
                default: property
                    .attribute("default")
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .map(str::to_owned),
                doc: property
                    .children()
                    .find(|c| c.has_tag_name("description"))
                    .and_then(|d| d.text())
                    .map(|t| t.trim().to_owned())
                    .filter(|t| !t.is_empty()),
            });
        }

        // `dummy` and `ethtool` have none, and a struct with no fields would be noise.
        if properties.is_empty() {
            continue;
        }

        settings.push(Setting {
            struct_name: format!("{}Setting", pascal_case(&field_name)),
            field_name,
            name: name.to_owned(),
            doc: node.attribute("description").map(str::to_owned),
            properties,
        });
    }

    if settings.is_empty() {
        bail!("no settings found — has the generated table changed shape?");
    }
    Ok(settings)
}

/// The field a setting becomes: its own name where that works, else the upper-case form
/// NetworkManager also gives (`802-3-ethernet` is `WIRED`), else an override.
fn field_name(name: &str, name_upper: Option<&str>, overrides: &[(String, String)]) -> Option<String> {
    if let Some((_, field)) = overrides.iter().find(|(setting, _)| setting == name) {
        return Some(field.clone());
    }
    let candidates = [Some(name), name_upper].into_iter().flatten();
    candidates
        .map(field_ident)
        .find(|candidate| candidate.starts_with(|c: char| c.is_ascii_alphabetic() || c == '_'))
}

/// `mac-address` -> `mac_address`, `IP4_CONFIG` -> `ip4_config`.
fn field_ident(name: &str) -> String {
    let ident = name.replace('-', "_").to_ascii_lowercase();
    // A handful of property names are Rust keywords.
    if matches!(ident.as_str(), "type" | "match" | "priority" | "fn" | "mod" | "ref") {
        return format!("{ident}_");
    }
    ident
}

/// `wireless_security` -> `WirelessSecurity`, `ieee8021x` -> `Ieee8021x`.
///
/// A word carrying digits keeps the rest of its spelling, so `802` and `p2p` survive; only the
/// first character is ever forced.
fn pascal_case(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for word in name.split('_').filter(|w| !w.is_empty()) {
        let mut chars = word.chars();
        let Some(first) = chars.next() else { continue };
        out.push(first.to_ascii_uppercase());
        if word.contains(|c: char| c.is_ascii_digit()) {
            out.push_str(chars.as_str());
        } else {
            out.extend(chars.map(|c| c.to_ascii_lowercase()));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    const TABLE: &str = r#"<nm-setting-docs>
      <setting name="802-3-ethernet" description="Wired Ethernet Settings" name_upper="WIRED">
        <property name="mac-address" type="byte array" default=""><description>The MAC.</description></property>
        <property name="mtu" type="uint32" default="0"/>
      </setting>
      <setting name="connection" description="General" name_upper="CONNECTION">
        <property name="metered" type="NMMetered (int32)" default="unknown"/>
        <property name="type" type="string"/>
      </setting>
      <setting name="802-11-wireless" description="Wi-Fi" name_upper="WIRELESS">
        <property name="security" type=""/>
        <property name="ssid" type="byte array"/>
      </setting>
      <setting name="dummy" description="Dummy" name_upper="DUMMY"/>
    </nm-setting-docs>"#;

    #[test]
    fn names_settings_from_whichever_form_works() {
        let settings = parse(TABLE, &[]).unwrap();
        let names: Vec<_> = settings
            .iter()
            .map(|s| (s.field_name.as_str(), s.struct_name.as_str()))
            .collect();
        assert_eq!(
            names,
            [
                ("wired", "WiredSetting"),
                ("connection", "ConnectionSetting"),
                ("wireless", "WirelessSetting"),
            ]
        );
    }

    #[test]
    fn reads_types_defaults_and_docs() {
        let settings = parse(TABLE, &[]).unwrap();
        let mac = &settings[0].properties[0];
        assert_eq!(mac.field_name, "mac_address");
        assert_eq!(mac.ty, PropertyType::ByteArray);
        assert_eq!(mac.doc.as_deref(), Some("The MAC."));

        assert_eq!(settings[0].properties[1].default.as_deref(), Some("0"));
        assert_eq!(
            settings[1].properties[0].ty,
            PropertyType::Named { c_name: "NMMetered".to_owned() }
        );
    }

    #[test]
    fn escapes_keywords_and_skips_untyped_and_empty() {
        let settings = parse(TABLE, &[]).unwrap();
        assert_eq!(settings[1].properties[1].field_name, "type_");
        // `security` has no type, `dummy` has no properties.
        assert_eq!(settings[2].properties.len(), 1);
        assert!(!settings.iter().any(|s| s.name == "dummy"));
    }

    #[test]
    fn rejects_an_unknown_type() {
        let table = TABLE.replace("byte array", "array of quaternions");
        let error = parse(&table, &[]).unwrap_err();
        assert!(format!("{error:#}").contains("array of quaternions"));
    }

    #[test]
    fn requires_an_override_for_unusable_names() {
        let table = TABLE.replace(
            r#"name="802-3-ethernet" description="Wired Ethernet Settings" name_upper="WIRED""#,
            r#"name="802-1x" description="Auth" name_upper="802_1X""#,
        );
        assert!(parse(&table, &[]).is_err());
        let overrides = [("802-1x".to_owned(), "ieee8021x".to_owned())];
        let settings = parse(&table, &overrides).unwrap();
        assert_eq!(settings[0].struct_name, "Ieee8021xSetting");
    }
}

#[cfg(test)]
mod vendored {
    /// The real table parses, and every type in it is one this module knows.
    ///
    /// This is the check that matters: the fixture above exercises the shapes, but only the
    /// vendored file proves that NetworkManager has not introduced a property type — or a
    /// setting whose name needs an override — that generation would otherwise reject.
    #[test]
    fn parses() {
        let source = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../spec/nm-settings-docs-dbus.xml"
        ))
        .expect("the vendored settings table is present");
        let overrides = crate::overrides::load(std::path::Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/.."
        )))
        .expect("annotations.toml parses");

        let settings = super::parse(&source, &overrides.setting_fields()).expect("the table parses");

        let properties: usize = settings.iter().map(|s| s.properties.len()).sum();
        assert!(
            settings.len() > 50 && properties > 500,
            "only {} settings and {properties} properties — the table looks truncated",
            settings.len()
        );
        assert!(settings.iter().all(|s| !s.field_name.is_empty()));
    }
}
